.site-header nav a{text-decoration:none}
.site-header nav .nav-active{color:var(--text);font-weight:700}
.network{color:var(--secondary);font-size:12px;margin-left:auto;gap:7px;align-items:center;display:flex}
.network i{height:7px;width:7px;background:#28af62;border-radius:50%;display:block}
main{max-width:var(--content-width);padding:54px 28px 90px;margin:auto}
.page-head{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:38px}
.page-head h1,.detail-head h1,.profile-head h1{font-size:42px;line-height:1.1;letter-spacing:-1.7px;margin:7px 0 10px}
.eyebrow{color:var(--accent);font-size:11px;font-weight:800;letter-spacing:1.7px;margin:0}
.subhead{color:var(--secondary);font-size:16px;margin:0;max-width:570px}
.total{text-align:right;border-left:1px solid var(--border);padding-left:34px}
.total span,.total strong{display:block}
.total span{font-size:12px;color:var(--secondary);text-transform:uppercase;letter-spacing:1px}
.total strong,.detail-pot strong{color:var(--accent);font-size:27px;letter-spacing:-.7px}
.filters{display:flex;gap:10px;align-items:center;padding:12px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border);margin-bottom:17px}
.filters label{color:var(--secondary);font-size:12px;display:flex;gap:7px;align-items:center}
.filters select,.search input{border:1px solid var(--border);background:#fff;border-radius:6px;color:var(--text);padding:8px 11px;font:inherit;font-size:13px}
.search{margin-right:auto;border:1px solid var(--border);background:#fff;border-radius:6px;padding:0 10px!important}
.search input{border:0;outline:0;width:210px;padding-left:3px}
.table-label{display:flex;justify-content:space-between;color:var(--secondary);font-size:11px;text-transform:uppercase;letter-spacing:1px;padding:8px 12px}
.board{list-style:none;padding:0;margin:0}
.bounty-row{display:grid;grid-template-columns:minmax(300px,1fr) 145px 150px 75px;gap:20px;align-items:center;border-top:1px solid var(--border);padding:19px 12px}
.bounty-row:hover{background:#fff}
.row-main .category{font-size:10px;letter-spacing:1.2px;text-transform:uppercase;color:var(--accent);font-weight:750}
.row-title{display:block;font-size:18px;font-weight:700;text-decoration:none;margin-top:3px}
.row-main p{margin:4px 0 0;color:var(--secondary);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.row-pot strong,.row-entries strong{display:block;font-size:17px}
.row-pot strong,.green{color:var(--accent)}
small,.row-pot small,.row-deadline small,.row-entries small{display:block;color:var(--secondary);font-size:11px}
.muted{color:var(--secondary)}
.time{font-weight:700}
.urgent{color:var(--warning)}
.empty,.loading{padding:35px 12px;color:var(--secondary)}
.crumb{color:var(--secondary);font-size:13px;margin:0 0 35px}
.crumb a{text-decoration:none;color:var(--text);font-weight:650}
.detail-head{display:flex;justify-content:space-between;align-items:end;gap:30px}
.detail-pot{min-width:180px;text-align:right}
.detail-pot span{display:block;color:var(--secondary);font-size:12px}
.detail-pot strong{display:block;margin:5px 0}
.tabs,.view-tabs{display:flex;gap:25px;border-bottom:1px solid var(--border);margin:37px 0 30px}
.tabs a,.view-tabs a{padding:0 0 12px;text-decoration:none;color:var(--secondary);font-size:13px}
.tabs .active,.view-tabs .selected{color:var(--text);font-weight:750;border-bottom:2px solid var(--accent)}
.detail-grid{display:grid;grid-template-columns:minmax(0,1fr) 370px;gap:70px}
.detail-copy h2,.detail-side h2,.submissions h2,.entries h2{font-size:17px;margin:0 0 14px}
.detail-copy h2:not(:first-child){margin-top:33px}
.prose{color:#425049;max-width:680px}
.prose p{margin:0 0 12px}
.prose h1,.prose h2,.prose h3{font-size:16px;color:var(--text);margin:19px 0 7px}
.rules{border-left:3px solid var(--tint);padding-left:18px}
.detail-side{background:#fff;border:1px solid var(--border);border-radius:7px;padding:22px}
.detail-side dl{display:grid;grid-template-columns:1fr 1fr;gap:9px 15px;border-bottom:1px solid var(--border);padding-bottom:19px;margin:0 0 21px}
.detail-side dt{color:var(--secondary);font-size:12px}
.detail-side dd{margin:0;text-align:right;font-weight:650}
.scroll-table{overflow-x:auto}
table{border-collapse:collapse;width:100%;font-size:13px}
th{text-align:left;color:var(--secondary);font-size:10px;letter-spacing:.8px;text-transform:uppercase;font-weight:700;white-space:nowrap}
th,td{border-bottom:1px solid var(--border);padding:10px 9px;white-space:nowrap}
td:first-child,th:first-child{padding-left:0}
.submissions{border-top:1px solid var(--border);margin-top:55px;padding-top:25px}
.section-title{display:flex;justify-content:space-between;align-items:center}
.section-title a{font-size:13px;text-decoration:none;color:var(--accent)}
.submission-list{display:grid;grid-template-columns:repeat(2,1fr);gap:0 35px}
.submission-list a{display:flex;align-items:center;gap:10px;text-decoration:none;border-top:1px solid var(--border);padding:13px 0}
.submission-list a>span:nth-child(2){flex:1}
.avatar{width:29px;height:29px;border-radius:50%;background:#d6e8dc;color:var(--accent);display:grid;place-items:center;font-size:10px;font-weight:750}
.live-tag{background:var(--tint);color:var(--accent);font-size:11px;font-weight:750;padding:7px 10px;border-radius:4px}
.leaderboard td a{color:var(--accent);text-decoration:none}
.rank{font-weight:750;margin-right:8px}
.prize-badge{background:#f3e5b7;color:#795e18;border-radius:3px;padding:2px 5px;font-size:10px}
.more-wrap{display:flex;align-items:center;gap:15px;justify-content:center;padding:25px}
.more-wrap button{border:1px solid var(--border);background:#fff;border-radius:5px;padding:9px 16px;font:inherit;font-size:13px}
.more-wrap button:disabled{opacity:.5}
.row-count{text-align:center;padding:20px}
.profile-head{display:grid;grid-template-columns:110px 1fr 200px;gap:25px;align-items:start}
.profile-avatar{width:100px;height:100px;border-radius:50%;background:#d6e8dc;display:grid;place-items:center;color:var(--accent);font-size:28px;font-weight:750;overflow:hidden}
.profile-avatar img{width:100%;height:100%;object-fit:cover}
.profile-intro h1{margin-top:4px}
.handle{color:var(--secondary);margin:0 0 13px}
.social-links{display:flex;gap:14px;font-size:12px}
.social-links a{text-decoration:none;color:var(--accent)}
.wallet{border-left:1px solid var(--border);padding-left:20px;font-size:13px}
.wallet span,.wallet small{display:block;color:var(--secondary);font-size:11px}
.wallet a{color:var(--accent);text-decoration:none;display:block;margin:4px 0 10px}
.record-stats{display:grid;grid-template-columns:repeat(5,1fr);border-top:1px solid var(--border);border-bottom:1px solid var(--border);margin:48px 0 38px;padding:20px 0}
.record-stats div{border-right:1px solid var(--border);padding-left:20px}
.record-stats div:first-child{padding-left:0}
.record-stats div:last-child{border:0}
.record-stats strong,.record-stats span{display:block}
.record-stats strong{font-size:22px}
.record-stats span{font-size:11px;color:var(--secondary);text-transform:uppercase;letter-spacing:.7px}
.error{text-align:center;padding:80px 10px}
.error h1{font-size:32px}
.error a{color:var(--accent)}
footer{max-width:var(--content-width);margin:auto;padding:20px 28px;border-top:1px solid var(--border);display:flex;justify-content:space-between;color:var(--secondary);font-size:10px;letter-spacing:1px}
footer a{color:var(--accent);text-decoration:none}
@media (max-width:700px){
.nav-inner{padding:0 17px;gap:18px}
.site-header nav a:last-child,.network{display:none}
main{padding:35px 17px 60px}
.page-head,.detail-head{display:block}
.page-head h1,.detail-head h1,.profile-head h1{font-size:34px}
.total{margin-top:25px;text-align:left;border-left:0;border-top:1px solid var(--border);padding:15px 0 0}
.filters{flex-wrap:wrap}
.search{width:100%;margin-right:0}
.search input{width:calc(100% - 20px)}
.bounty-row{grid-template-columns:1fr 1fr;gap:12px;padding:17px 5px}
.row-main{grid-column:1/-1}
.row-pot{text-align:left}
.row-deadline{text-align:right}
.row-entries{grid-column:2;text-align:right}
.detail-grid{display:block}
.detail-side{margin-top:35px}
.submission-list{grid-template-columns:1fr}
.profile-head{grid-template-columns:75px 1fr}
.profile-avatar{width:70px;height:70px;font-size:20px}
.wallet{grid-column:1/-1;border-left:0;border-top:1px solid var(--border);padding:15px 0 0}
.social-links{flex-wrap:wrap}
.record-stats{grid-template-columns:repeat(3,1fr);gap:18px}
.record-stats div{border:0;padding:0}
.record-stats div:nth-child(n+4){display:none}
.tabs{gap:16px;overflow-x:auto}
.table-label{padding-left:5px}
.detail-pot{text-align:left;margin-top:22px}
}
@media (prefers-reduced-motion:reduce){
*{scroll-behavior:auto!important;transition:none!important}
}
